import{_ as n,o as r,c as a,a2 as s}from"./chunks/framework.BBd5PKnH.js";const o="/dev-notes/assets/Screenshot%202026-10-05%20at%2015.39.36.Vbl6026-.png",h="/dev-notes/assets/Screenshot%202026-10-05%20at%2016.02.25.BkrUzOcQ.png",p=JSON.parse('{"title":"Lựa chọn PostgreSQL trên AWS: EC2 tự host vs RDS vs Aurora","description":"","frontmatter":{},"headers":[],"relativePath":"notes/aurora_vs_rds.md","filePath":"notes/aurora_vs_rds.md"}'),e={name:"notes/aurora_vs_rds.md"};function i(c,t,l,u,g,d){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="lua-chon-postgresql-tren-aws-ec2-tu-host-vs-rds-vs-aurora" tabindex="-1">Lựa chọn PostgreSQL trên AWS: EC2 tự host vs RDS vs Aurora <a class="header-anchor" href="#lua-chon-postgresql-tren-aws-ec2-tu-host-vs-rds-vs-aurora" aria-label="Permalink to &quot;Lựa chọn PostgreSQL trên AWS: EC2 tự host vs RDS vs Aurora&quot;">​</a></h1><p>Có ba cách chạy PostgreSQL trên AWS:</p><ul><li><strong>PostgreSQL tự cài trên EC2</strong> — tự quản lý toàn bộ.</li><li><strong>Amazon RDS</strong> — dịch vụ database quản lý sẵn (managed), phù hợp cho tải nhỏ.</li><li><strong>Amazon Aurora</strong> (tương thích MySQL + PostgreSQL) — phù hợp cho app chịu tải nhiều, truy xuất nhiều.</li></ul><p>RDS và Aurora đều là dịch vụ <strong>fully-managed</strong>: chỉ việc dùng, không cần tự cài đặt hay cập nhật thư viện/phiên bản — tiết kiệm thời gian vận hành so với tự host trên EC2.</p><h2 id="tu-host-tren-ec2" tabindex="-1">Tự host trên EC2 <a class="header-anchor" href="#tu-host-tren-ec2" aria-label="Permalink to &quot;Tự host trên EC2&quot;">​</a></h2><ul><li><strong>Ưu điểm</strong>: toàn quyền kiểm soát (cấu hình, phiên bản, hệ điều hành...).</li><li><strong>Nhược điểm</strong>: tốn nhiều nhân lực hơn để bảo trì (cài đặt, vá lỗi, backup, theo dõi...).</li></ul><p><img src="'+o+'" alt="RDS vs Aurora overview"></p><h2 id="rds" tabindex="-1">RDS <a class="header-anchor" href="#rds" aria-label="Permalink to &quot;RDS&quot;">​</a></h2><ul><li>Dịch vụ database quan hệ managed của AWS, hỗ trợ nhiều engine (PostgreSQL, MySQL...).</li><li>Phù hợp cho các ứng dụng có tải vừa và nhỏ.</li></ul><p><img src="'+h+'" alt="RDS detail"></p><h2 id="aurora-vs-rds" tabindex="-1">Aurora vs RDS <a class="header-anchor" href="#aurora-vs-rds" aria-label="Permalink to &quot;Aurora vs RDS&quot;">​</a></h2><ul><li>Aurora là engine database do AWS tự phát triển, tương thích API với MySQL và PostgreSQL, nhưng có kiến trúc lưu trữ riêng (tách compute và storage) giúp hiệu năng và khả năng mở rộng tốt hơn RDS thông thường.</li><li>Nên chọn <strong>RDS</strong> khi tải nhỏ, ưu tiên chi phí thấp và đơn giản.</li><li>Nên chọn <strong>Aurora</strong> khi ứng dụng cần chịu tải cao, đọc/ghi nhiều, cần khả năng mở rộng và độ sẵn sàng cao hơn.</li></ul>',12)])])}const S=n(e,[["render",i]]);export{p as __pageData,S as default};
